[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Action action)
{
    // Warmup
    for (int i = 0; i < 1000; i++) action();

    // Find iteration count that takes ~500ms
    int iters = 1000;
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < iters; i++) action();
    sw.Stop();
    double perCall = sw.Elapsed.TotalMilliseconds / iters;
    iters = Math.Max(1000, (int)(500.0 / perCall));

    // Run 10 rounds, collect timings
    const int rounds = 10;
    double[] timings = new double[rounds];
    for (int r = 0; r < rounds; r++)
    {
        sw.Restart();
        for (int i = 0; i < iters; i++) action();
        sw.Stop();
        timings[r] = sw.Elapsed.TotalNanoseconds / iters;
    }

    double mean = timings.Average();
    double stddev = Math.Sqrt(timings.Select(t => (t - mean) * (t - mean)).Average());

    string unit = "ns";
    double displayMean = mean, displayStd = stddev;
    if (mean >= 1_000_000) { displayMean /= 1_000_000; displayStd /= 1_000_000; unit = "ms"; }
    else if (mean >= 1_000) { displayMean /= 1_000; displayStd /= 1_000; unit = "µs"; }

    Console.WriteLine($"{name,-35} {displayMean,9:F2} {unit} {displayStd,9:F2} {unit} {iters,12}");
}

